{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-08",
  "sketch": {
    "components": ["Internal AI agent", "MCP server discovery/installer", "MCP tool runtime", "Agent tool-call loop"],
    "dataStores": [],
    "externalServices": ["Public MCP registry", "Third-party MCP servers"],
