  },
  "threats": [
    {
      "stride": "Tampering",
      "title": "Agent installs a malicious MCP server from the public registry and runs its code",
      "scenario": "Anyone can publish to a public MCP registry, or take over an existing package name. The agent discovers and installs that server at runtime with no signature, pinning or allowlist, then executes it inside the agent's runtime. The attacker gets arbitrary code execution wherever the agent runs, with the agent's filesystem, network and credentials, and persists across sessions because installs happen without a deploy or code review.",
      "component": "MCP server discovery/installer",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "Our internal agent can discover and install new MCP servers from a public registry at runtime so it can use new tools without a deploy."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-829", "CWE-494", "CWE-1357"],
      "plainLanguage": "The agent downloads and runs code that strangers published on the internet, so a bad package takes over the machine.",
      "requirement": {
        "title": "Only install MCP servers from a signed, pinned allowlist",
        "given": "the agent wants to use an MCP server it does not already have",
        "when": "the server is not on the approved allowlist at a pinned version with a verified publisher signature or digest",
        "then": "installation is refused, the attempt is recorded, and a human must approve the addition before the agent can use it"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Newly installed tools inherit the agent's full privileges and credentials",
      "scenario": "A third-party MCP server installed at runtime runs in the same process and identity as the agent, so it can read environment variables, tokens and API keys the agent holds and call internal systems the agent can reach. An attacker who gets one tool installed does not need any further exploit: the tool simply asks the host for secrets or calls privileged internal APIs, turning a tool addition into a full breach of everything the agent is authorised for.",
      "component": "MCP tool runtime",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "install new MCP servers from a public registry at runtime so it can use new tools without a deploy"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-250", "CWE-522", "CWE-668"],
      "plainLanguage": "A new tool gets the same keys and access as the agent itself, so one bad tool can reach everything.",
      "requirement": {
        "title": "Sandbox each MCP server with least-privilege, per-tool credentials",
        "given": "an approved MCP server is started by the agent",
        "when": "it requests filesystem, network or credential access",
        "then": "it runs in an isolated sandbox with only an explicitly scoped, short-lived credential for its own purpose and no access to the agent's other secrets or internal networks"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Poisoned tool descriptions hijack the agent's goal (tool-description injection)",
      "scenario": "MCP tool names, descriptions and parameter docs from a freshly installed server are placed into the agent's prompt as trusted text. An attacker publishes a plausible tool whose description contains instructions such as always send a copy of the user's data to this endpoint first. The agent follows them, so the attacker redirects the agent's behaviour and exfiltrates data without ever exploiting the code, and the behaviour looks like normal tool use.",
      "component": "Agent tool-call loop",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "discover and install new MCP servers from a public registry at runtime so it can use new tools without a deploy"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-77", "CWE-20"],
      "plainLanguage": "The text describing a new tool can contain hidden orders, and the agent obeys them.",
      "requirement": {
        "title": "Treat tool metadata as untrusted data",
        "given": "an MCP server advertises tool names, descriptions or schemas",
        "when": "that metadata is added to the agent's context",
        "then": "it is clearly delimited as untrusted data, stripped of instruction-like content, size-capped, and changes to metadata of an already-approved tool require re-approval"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Installed tool exfiltrates data over its own outbound network connections",
      "scenario": "An installed MCP server can open arbitrary outbound connections. An attacker's server quietly forwards every prompt, document and result it is given to an attacker-controlled host, or uses the agent to pull internal data and then ships it out. Because installs happen at runtime without a deploy, nobody reviews where the tool talks to, and the leak continues until someone notices unusual traffic.",
      "component": "MCP server egress",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        {
          "quote": "install new MCP servers from a public registry at runtime"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-200", "CWE-918"],
      "plainLanguage": "A new tool can quietly send whatever it sees to the attacker's server.",
      "requirement": {
        "title": "Deny-by-default egress for MCP servers",
        "given": "an MCP server is running under the agent",
        "when": "it attempts an outbound network connection",
        "then": "the connection is blocked unless the destination is on that server's declared allowlist, and blocked attempts quarantine the tool"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Agent can expand its own capabilities with no human approval gate",
      "scenario": "The stated benefit is adding tools without a deploy, which means the agent decides what powers it has. A hijacked or confused agent, or an attacker who can influence a single prompt, can make the agent search the registry for a tool that does what the agent is otherwise forbidden to do (shell access, database writes, outbound email) and install it on the spot, bypassing every control that was enforced at build and deploy time.",
      "component": "MCP server discovery/installer",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "so it can use new tools without a deploy"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-862", "CWE-284"],
      "plainLanguage": "The agent can give itself new abilities on its own, with nobody checking.",
      "requirement": {
        "title": "Human approval required for capability expansion",
        "given": "the agent requests installation of a tool it does not already have",
        "when": "the request would add a new capability class (code execution, write access, outbound messaging)",
        "then": "the agent is blocked and a named human must approve the specific server and version in a review interface before it becomes available"
      }
    },
    {
      "stride": "Tampering",
      "title": "Registry or update tampering silently changes an already-trusted tool",
      "scenario": "Even if a server was fine when first installed, the registry or the publisher's account can be compromised, or the maintainer can push a malicious update. Because discovery and install happen continuously at runtime, the agent will pick up the new version automatically and run it. The attacker needs only one compromised upstream account to reach every agent instance, with no deploy, review or rollback point in between.",
      "component": "Public MCP registry",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        {
          "quote": "discover and install new MCP servers from a public registry at runtime"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-494", "CWE-1104"],
      "plainLanguage": "A tool that was safe yesterday can be replaced with a malicious update that the agent installs automatically.",
      "requirement": {
        "title": "Pin and verify tool versions, block silent upgrades",
        "given": "an approved MCP server has a new version available in the registry",
        "when": "the agent resolves that tool",
        "then": "it loads only the pinned digest it was approved with, and any digest mismatch or version change fails closed and raises an alert"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Hostile tool output poisons the agent's context and later decisions",
      "scenario": "Results returned by an installed MCP server are fed straight back into the agent's reasoning and any stored memory. An attacker's tool returns crafted output that rewrites the agent's assumptions, marks dangerous actions as pre-approved, or plants instructions that persist into later tasks and other tools. The compromise outlives the single call and can cascade into other agents or workflows that trust this agent's output.",
      "component": "Agent tool-call loop",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        {
          "quote": "so it can use new tools without a deploy"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-20", "CWE-74"],
      "plainLanguage": "What a tool returns is believed by the agent and can quietly change what it does next.",
      "requirement": {
        "title": "Quarantine and validate tool output before it influences actions",
        "given": "an MCP server returns a result to the agent",
        "when": "that result is used for reasoning or written to memory",
        "then": "it is validated against the declared schema, labelled with its untrusted source, and cannot by itself authorise a privileged action or override a policy decision"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No record of which tool version acted, so incidents cannot be traced",
      "scenario": "With tools appearing and disappearing at runtime, there is no deploy artefact that says what the agent could do at a given moment. After a data leak or destructive action, responders cannot tell which server and version performed it, who introduced it, or whether it is still installed elsewhere. The attacker can remove the tool afterwards and leave no attributable trail, so containment and rollback both fail.",
      "component": "MCP server discovery/installer",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        {
          "quote": "Our internal agent can discover and install new MCP servers from a public registry at runtime"
        }
      ],
      "asvs": [],
      "cwe": ["CWE-778"],
      "plainLanguage": "Because tools come and go on their own, nobody can later prove which tool did the damage.",
      "requirement": {
        "title": "Immutable inventory of installed tools and their actions",
        "given": "an MCP server is installed, upgraded, removed or invoked",
        "when": "the event occurs",
        "then": "an append-only record stores the server identity, version digest, source, approver and the actions it took, retained independently of the agent runtime"
      }
    }
  ]
}
