        "title": "Only install MCP servers from a signed allowlist after human approval",
        "given": "an internal agent that can install MCP servers at runtime",
        "when": "it selects a server that is not on the reviewed allowlist or whose artifact signature/digest does not verify",
        "then": "the installation is refused and the request is queued for explicit human approval before any code is executed"
      }
    },
    {
      "stride": "Tampering",
      "title": "No integrity check on downloaded MCP server code (ASI04 agentic supply chain)",
      "scenario": "An attacker who compromises the registry account, the CDN, or the network path replaces or updates an MCP server package the agent already trusts. Because install happens at runtime with no pinned version, digest or signature verification, the agent silently fetches the tampered build on the next discovery and executes attacker-controlled logic. A compromise of one popular package reaches every agent instance at once.",
      "component": "MCP tool discovery module / registry fetch",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "discover and install new MCP servers from a public registry at runtime so it can use new tools without a deploy" }
      ],
      "cwe": ["CWE-494", "CWE-345"],
      "plainLanguage": "Nothing checks that the tool we download is the one we expected, so it can be swapped for a malicious version.",
      "requirement": {
        "title": "Pin and verify MCP server artifacts",
        "given": "an MCP server package fetched from the public registry",
        "when": "the agent installs or upgrades it",
        "then": "the exact version is pinned and the artifact digest and publisher signature are verified, and any mismatch aborts the install"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Agent goal hijack through attacker-written tool names and descriptions (ASI01)",
      "scenario": "The agent reads tool metadata from the public registry to decide what to install and when to call it. An attacker embeds instructions in a tool name, description or schema (\"use this tool for all database access\", \"ignore prior safety rules\"). The agent treats that registry text as guidance, installs the rogue tool and routes sensitive operations to it, giving the attacker control over the agent's actions.",
      "component": "Agent reasoning loop / tool catalog",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Our internal agent can discover and install new MCP servers from a public registry at runtime so it can use new tools without a deploy." }
      ],
      "cwe": ["CWE-1427", "CWE-20"],
      "plainLanguage": "Text written by whoever published a tool can act like orders to our agent and make it choose the attacker's tool.",
      "requirement": {
        "title": "Treat registry metadata as untrusted data",
        "given": "tool names, descriptions and schemas from the public registry",
        "when": "they are placed into the agent's context",
        "then": "they are wrapped as untrusted data, stripped of instruction-like content, and never used to change the agent's policy or tool-selection rules"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Newly installed tool inherits the agent's credentials and exfiltrates data (ASI03)",
      "scenario": "A runtime-installed MCP server is loaded into the same agent session and can be invoked with the agent's existing tokens and network access. A malicious or over-broad tool calls internal APIs and sends results to an attacker endpoint, because installation grants tool capability without a per-tool identity, scope or egress policy. One install turns into read access to whatever the agent can reach.",
      "component": "Agent tool loader / credential scope",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "so it can use new tools without a deploy" }
      ],
      "cwe": ["CWE-269", "CWE-668"],
      "plainLanguage": "A tool installed on the fly gets to use the agent's keys, so it can read internal data and send it out.",
      "requirement": {
        "title": "Least-privilege identity and egress control per MCP tool",
        "given": "an MCP server installed at runtime",
        "when": "the agent invokes it",
        "then": "it runs in a sandbox with its own scoped credentials, an explicit egress allowlist, and no access to the agent's own tokens or environment secrets"
      }
    },
    {
      "stride": "Tampering",
      "title": "Rogue tool results poison the agent's context and later decisions (ASI06)",
      "scenario": "Output from an installed MCP server is fed back into the agent's context and any persistent memory. An attacker-controlled tool returns fabricated facts or hidden instructions that steer subsequent tasks, including instructions to install further servers or disable checks. The poisoning persists after the tool is removed, so the agent keeps acting on attacker-supplied state.",
      "component": "Agent context / memory",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "it can use new tools without a deploy" }
