      "requirement": {
        "title": "Quarantine and label tool output",
        "given": "a response from a dynamically installed MCP server",
        "when": "it enters the agent context or memory",
        "then": "it is labelled untrusted, excluded from persistent memory unless validated, and cannot trigger install or privilege changes"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Agent self-expands its own capabilities with no human gate (ASI09/ASI10)",
      "scenario": "The design's stated goal is new capability without a deploy, so the agent decides on its own which tools it may have. An operator reviewing the agent cannot know what it can do at any moment, and an attacker who nudges the agent once (via a prompt, ticket or web page it reads) can make it acquire powerful tools such as shell or cloud-admin MCP servers, escaping every control the deploy pipeline used to enforce.",
      "component": "Agent install decision logic",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "install new MCP servers from a public registry at runtime so it can use new tools without a deploy" }
