      "plainLanguage": "The agent can give itself new powers whenever it wants, with nobody approving it.",
      "requirement": {
        "title": "Human-in-the-loop capability expansion",
        "given": "an agent requesting a new MCP tool",
        "when": "the tool is not already approved for that agent's role",
        "then": "the agent is blocked and a named human must approve the specific tool and scope in a reviewed catalog before it becomes callable"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Untrusted tool installs crash or exhaust the agent host and cascade (ASI08)",
      "scenario": "Runtime installs pull arbitrary dependencies and spawn arbitrary processes. A faulty or deliberately heavy MCP server consumes CPU, memory, disk or file descriptors, or hangs on every call, taking down the shared agent runtime and every workflow that depends on it. With no resource limits, timeouts or rollback, one bad registry entry stops the service for all users.",
      "component": "Agent runtime host",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "discover and install new MCP servers from a public registry at runtime" }
      ],
      "cwe": ["CWE-400"],
      "plainLanguage": "A broken or greedy tool installed automatically can hog resources and take the whole agent offline.",
      "requirement": {
        "title": "Resource limits and automatic rollback for installed tools",
        "given": "a newly installed MCP server",
        "when": "it exceeds CPU, memory, disk or call-timeout limits",
        "then": "it is killed, uninstalled automatically and the agent continues with its previously approved tool set"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No record of which tool version acted, so incidents cannot be reconstructed",
      "scenario": "Because the tool set changes continuously outside the deploy pipeline, after a damaging action nobody can say which MCP server, version or publisher was installed at that moment or what it was asked to do. An attacker whose package is installed and then superseded leaves no trace, and the organisation cannot scope the breach or prove which actions were attacker-driven.",
      "component": "Agent tool catalog / install history",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "so it can use new tools without a deploy" }
      ],
      "cwe": ["CWE-778"],
      "plainLanguage": "Since tools change on their own without a release, we cannot later tell which tool did what.",
      "requirement": {
        "title": "Immutable install and invocation ledger",
        "given": "an MCP server install, upgrade, removal or invocation",
        "when": "the event occurs",
        "then": "an append-only record of server name, version, source, digest, approver and invocation arguments is written to storage the agent cannot modify"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Registry discovery requests reach attacker-chosen internal endpoints (SSRF)",
      "scenario": "The agent fetches registry entries and then the install locations they point at. An attacker publishes an entry whose download or MCP endpoint URL points at internal addresses such as cloud metadata or admin services. The installer follows it from inside the network, returning internal responses or instance credentials to the attacker through the agent's output.",
      "component": "MCP registry fetch / installer",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "discover and install new MCP servers from a public registry at runtime" }
      ],
      "cwe": ["CWE-918"],
      "plainLanguage": "A tool listing can point the agent at our own internal addresses and get secrets back.",
      "requirement": {
        "title": "Validate and restrict install URLs",
        "given": "a download or endpoint URL supplied by the registry",
